/* ── Model-fallback cause formatting (SINGLE source) ──────────────────
 *
 * ConversationSurface delegates terminal fallback details to finish_info.js.
 * Formatting lives here once so every non-conversation consumer uses the same
 * normalization throat as the Turn footer.
 * Kind labels resolve through the same chain renderErrorEnvelope uses. */

/* Visible-cause budget. The verbatim text (which can be an entire upstream
 * HTML error page, as with a bare openresty 502) is kept by callers in a
 * title attribute; only the VISIBLE line is capped. */
const FALLBACK_DETAIL_MAX = 160;

/* Distill an upstream error body down to its human signal.
 *
 * A gateway 5xx often arrives as a whole HTML page, so the raw detail reads
 * '<html> <head><title>502 Bad Gateway</title></head> <body> <center><h1>502
 * Bad Gateway</h1></center> <hr><center>openresty</center>...' — technically
 * the cause, but the reader has to mine it out of markup. Keep any leading
 * non-markup prefix (the 'API HTTP 502:' our own layer adds), then replace
 * the markup tail with the page's own de-duplicated text nodes:
 * '502 Bad Gateway · openresty'. Returns the input UNTOUCHED when there are
 * no tags, so a plain message (the common case: rate limits, timeouts) is
 * never reworded — this is a de-noiser, not a rewriter. */
function distillFallbackDetail(detail) {
  const lt = detail.indexOf('<');
  if (lt === -1 || !/<\/?[a-zA-Z][^>]*>/.test(detail)) return detail;
  const prefix = detail.slice(0, lt).trim();
  const stripped = detail.slice(lt)
    .replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, ' ')
    .replace(/<[^>]*>/g, '\u0001');            // tag → text-node separator
  const seen = [];
  for (const piece of stripped.split('\u0001')) {
    const s = piece.replace(/\s+/g, ' ').trim();
    /* A <title> repeats the <h1> on nginx/openresty pages — dedupe so the
     * distilled line reads once, not three times. */
    if (s && seen.indexOf(s) === -1) seen.push(s);
  }
  const body = seen.join(' \u00b7 ');
  if (!body) return prefix || detail;
  return prefix ? `${prefix} ${body}` : body;
}

/* Human label for a typed error kind (keyed i18n → ERROR_KIND_LABELS → raw
 * kind), so a fallback cause and an error block never disagree on a name. */
function fallbackKindLabel(kind) {
  if (!kind) return '';
  const loc = _envResolveI18n('err.k.' + kind + '.chip');
  if (loc) return loc;
  return ERROR_KIND_LABELS[kind] || kind;
}

/* Resolve a message's fallback cause into display parts.
 *
 * Returns { kind, kindLabel, detail, shown, hasCause } where `detail` is the
 * verbatim (whitespace-collapsed) cause for a title attribute and `shown` is
 * the distilled + length-capped text safe to render VISIBLY. */
function fallbackCauseParts(msg) {
  const kind = (msg && msg.fallbackKind) || '';
  let detail = String((msg && msg.fallbackReason) || '');
  /* The backend composes the field as `${kind}: ${detail}`
   * (lib/tasks_pkg/llm_fallback/_call.py), so drop the kind prefix — it is
   * already rendered as its own label and would otherwise print twice. */
  if (kind && detail.indexOf(kind + ':') === 0) detail = detail.slice(kind.length + 1);
  detail = detail.replace(/\s+/g, ' ').trim();
  const distilled = distillFallbackDetail(detail);
  const shown = distilled.length > FALLBACK_DETAIL_MAX
    ? distilled.slice(0, FALLBACK_DETAIL_MAX) + '\u2026' : distilled;
  const kindLabel = fallbackKindLabel(kind);
  return { kind, kindLabel, detail, shown, hasCause: !!(kindLabel || shown) };
}

runtimeScope.renderErrorEnvelope = renderErrorEnvelope;
runtimeScope.normalizeErrorEnvelope = normalizeErrorEnvelope;
runtimeScope.errorEnvelopeKind = errorEnvelopeKind;
runtimeScope.errorEnvelopeMessage = errorEnvelopeMessage;
runtimeScope.isErrorEnvelope = isErrorEnvelope;
runtimeScope.distillFallbackDetail = distillFallbackDetail;
runtimeScope.fallbackKindLabel = fallbackKindLabel;
runtimeScope.fallbackCauseParts = fallbackCauseParts;
/* ===== migrated source: core/model_caps.js ===== */
/* ═══════════════════════════════════════════════════════════════════
   core/model_caps.js — capability taxonomy consumer

   Frontend counterpart of lib/model_info/capability_taxonomy.py. Owns the
   single answer to "is this model a chat model?" for every UI picker.

   Boot order: this file loads early in the CORE bundle so every downstream
   filter (main_toolbar_ui / paper/report / settings/visibility_defaults /
   settings/template_actions) can call runtimeScope.isChatModel(m).

   At boot the module holds a hardcoded fallback set (the frontend-only
   "chat picker" set — NOT the dispatcher's issubset set; those two differ
   by {'audio_chat'} and that difference is intentional — see
   lib/model_info/capability_taxonomy.py's module docstring).

   Once /api/server-config returns, main_toolbar_ui.js pipes its
   capability_taxonomy field through applyCapabilityTaxonomy(payload) so a
   deployment that adds a NEW non-chat cap (e.g. 'tts', 'video_gen') gets
   correct filtering without a client rebuild.

   This file is concatenated by Vite's module graph; symbols share the global
   window scope. No exports.
   ═══════════════════════════════════════════════════════════════════ */

(function() {
  // Hardcoded fallback — MUST match lib.model_info.capability_taxonomy
  // CHAT_EXCLUDED_CAPS exactly. The Python-side parity test
  // (test_capability_taxonomy_parity.py) enforces byte-equivalence.
  var _FALLBACK_CHAT_EXCLUDED_CAPS = ['image_gen', 'embedding', 'transcription', 'tts'];

  // The live set (may be overwritten by the server payload).
  var _chatExcludedCaps = new Set(_FALLBACK_CHAT_EXCLUDED_CAPS);

  // The dispatcher-shaped set — exposed for debugging / parity harnesses.
  // The frontend never filters with this; it's the backend's ``issubset``
  // set (frontend uses _chatExcludedCaps which excludes 'audio_chat').
  var _dispatcherNonChatCaps = new Set(_FALLBACK_CHAT_EXCLUDED_CAPS.concat(['audio_chat']));

  /** Return true if a model belongs in a chat picker.
   *
   * A caps list that's empty or missing counts as chat (matches the legacy
   * ``caps || ['text']`` default the old inline filters used). Any cap in
   * the exclusion set means "hide from chat picker".
   */
  function isChatModel(m) {
    if (!m) return true;
    var caps = m.capabilities;
    if (!caps || caps.length === 0) return true;
    for (var i = 0; i < caps.length; i++) {
      if (_chatExcludedCaps.has(caps[i])) return false;
    }
    return true;
  }

  /** Ingest the taxonomy payload from /api/server-config or /api/v1/capabilities.
   *
   * Best-effort: if the payload is missing / malformed the module keeps its
   * hardcoded fallback and logs a warning. Ignores the dispatcher-shaped
   * set for filtering purposes — the frontend filter is strictly
   * chat_excluded_caps (frontend semantics; audio_chat is legit chat).
   */
  function applyCapabilityTaxonomy(payload) {
    if (!payload || typeof payload !== 'object') return;
    var xs = payload.chat_excluded_caps;
    if (Array.isArray(xs) && xs.length > 0) {
      _chatExcludedCaps = new Set(xs);
    }
    var ds = payload.dispatcher_non_chat_caps;
    if (Array.isArray(ds) && ds.length > 0) {
      _dispatcherNonChatCaps = new Set(ds);
    }
  }

  /** Return the current chat-excluded set (for debug / tests). */
  function getChatExcludedCaps() {
    return new Set(_chatExcludedCaps);
  }

  runtimeScope.isChatModel = isChatModel;
  runtimeScope.applyCapabilityTaxonomy = applyCapabilityTaxonomy;
  runtimeScope.getChatExcludedCaps = getChatExcludedCaps;
  // Exposed as arrays so tests / debug consoles can read them without going
  // through Set() serialization.
  runtimeScope.CHAT_EXCLUDED_CAPS_FALLBACK = _FALLBACK_CHAT_EXCLUDED_CAPS.slice();
})();

