const _PT_CHEVRON_RIGHT_SVG = '<svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true"><path d="m6.5 5 3 3-3 3" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';

function _plainToolStatus(value, fallback) {
  return String(value || fallback || '').replace(/^[✓✗⊘⏸]\s*/u, '').trim();
}

// Round type detection
function _isRoundFetch(round) {
  return (
    round.toolName === "fetch_url" ||
    (round.query || "").startsWith("📄") ||
    (round.query || "").startsWith("🌐") ||
    (round.query || "").startsWith("📑")
  );
}
function _isRoundSearch(round) {
  return round.toolName === "web_search" || round.toolName === "search_knowledge";
}
function _isRoundToolSearch(round) {
  return round.toolName === "search_tools";
}
function _isRoundCodeExec(round) {
  return round.toolName === "code_exec";
}
function _isRoundProject(round) {
  return [
    "read_files",
    "inspect_image",
    "list_dir",
    "grep_search",
    "find_files",
    "write_file",
    "edit_file",
    "apply_diff",
    "apply_diffs",
    "insert_content",
    "insert_contents",
    "create_project",
    "run_command",
  ].includes(round.toolName);
}
/* Canonical browser family. This list exactly mirrors BROWSER_TOOL_NAMES,
 * ADVANCED_BROWSER_TOOL_NAMES, and PAGE_PREVIEW_TOOL_NAMES; the parity test
 * prevents a new tool from silently falling back to generic UI. */
const _BROWSER_TOOL_FAMILY = [
  "browser_list_tabs",
  "browser_read_page",
  "browser_research_page",
  "browser_devtools",
  "browser_execute_js",
  "browser_screenshot",
  "browser_click",
  "browser_type",
  "browser_press_key",
  "browser_navigate",
  "browser_close_tab",
  "browser_get_cookies",
  "browser_get_history",
  "browser_menu_click",
  "browser_fill_form",
  // Server-side preview (browser family, not extension-routed)
  "browser_preview_page",
];
function _isRoundBrowser(round) {
  return _BROWSER_TOOL_FAMILY.includes(round.toolName);
}
function _isRoundImageGen(round) {
  return round.toolName === "generate_image";
}
/* Tools whose prose belongs in the collapsible conversation-metadata block. */
