/* ════════════════════════════════════
   memory_skill_install.js — skill-package (.zip) drag/drop install
   Extracted from memory.js (2026-07). The skill-package install layer:
   _attachMemoryDropZone (OS file drag/drop) + installSkillFromFileInput +
   _uploadSkillPackage (Api.skills.install) + _showInstallToast. A distinct
   concern from memory-card CRUD. NOTE: skill packages are a different noun
   from memories — an install from this modal lands in the Skills tab, NOT
   in the memory list (post-split purification, 2026-07). Plain window-scope concatenation (NOT an
   IIFE) — _attachMemoryDropZone is called at runtime from openMemoryModal;
   calls back into _buildMemoryCardEl/_updateMemoryStats/_memoryCache in
   memory.js. Load order is free (both before main.js).
   ════════════════════════════════════ */

// ══════════════════════════════════════════════════════
// Skill-Package Install — drag-and-drop .zip into modal
// ══════════════════════════════════════════════════════

let _memoryDropAttached = false;

function _attachMemoryDropZone() {
  if (_memoryDropAttached) return;
  const modal = document.getElementById("memoryModal");
  const card  = modal ? modal.querySelector(".memory-modal") : null;
  if (!modal || !card) return;
  // Shared OS-file .zip drag/drop wiring (core/zip_drop_zone.js). The upload +
  // toast callbacks stay local (memory-specific scope + incremental card render).
  _memoryDropAttached = attachZipDropZone({
    listenEl: modal,
    highlightEl: card,
    onFile: (f) => _uploadSkillPackage(f),
    onReject: () => _showInstallToast(t('memory.notZip'), true),
  });
}

function installSkillFromFileInput(inputEl) {
  const f = inputEl && inputEl.files && inputEl.files[0];
  if (!f) return;
  _uploadSkillPackage(f);
  inputEl.value = "";  // allow re-selecting the same file
}

async function _uploadSkillPackage(file) {
  const activeTab = document.querySelector(".memory-tab.active");
  const tabScope = activeTab?.dataset?.scope;
  const scope = (tabScope === "global") ? "global" : "project";

  _showInstallToast(t('memory.installingFile', { name: file.name }));
  const fd = new FormData();
  fd.append("file", file);
  fd.append("scope", scope);

  try {
    const r = await Api.skills.install(fd);
    const d = (r ? await r.json().catch(() => ({})) : {});
    if (!r || !r.ok) {
      const _err = d.error || (r && r.statusText) || t('memory.noResponse');
      _showInstallToast(t('memory.installFailed', { err: _err }), true);
      debugLog("Skill install failed: " + _err, "error");
      return;
    }

    const mem = d.memory || {};
    const hints = d.install_hints || [];
    let msg = t('memory.installedPackage', { name: mem.name, scope: mem.scope });
    if (d.replaced) msg += t('memory.replacedOld');
    if (hints.length) {
      const files = hints.map(h => h.file).join(", ");
      msg += t('memory.installHintSuffix', { files: files });
    }
    _showInstallToast(msg);
    debugLog(msg, "success");
    // Skill packages live in the Settings → Skills tab (a different noun
    // from memories) — do NOT insert a card into the memory list.
    debugLog("Skill package installed — manage it in Settings → Skills tab");
  } catch (e) {
    _showInstallToast(t('memory.installError', { err: e.message }), true);
    debugLog("Skill install error: " + e.message, "error");
  }
}

function _showInstallToast(text, isError) {
  const modal = document.getElementById("memoryModal");
  const card = modal ? modal.querySelector(".memory-modal") : null;
  // Shared fade-out plumbing (core/toast.js::_ephemeralToast); keeps this
  // toast's in-modal-card parent + .memory-install-toast class.
  _ephemeralToast(card, "memory-install-toast" + (isError ? " is-error" : ""),
                  text, isError ? 5000 : 3500);
}

/* ===== migrated source: skills_install.js ===== */
/* ════════════════════════════════════
   skills_install.js — skill-package (.zip) drag/drop + upload + toast
   Extracted from skills.js (2026-07). The install-transport layer of the
   Skills tab: _skillsAttachDropZone (OS file drag/drop) + _skillsInstallFromInput
   + _skillsUploadZip (Api.skills.install) + _openSkillsStoreFromMemory +
   _skillsToast. Plain window-scope concatenation (NOT an IIFE) —
   _skillsAttachDropZone is called at runtime from _populateSkillsTab; the OS
   drag/drop plumbing is now the shared core/zip_drop_zone.js helper, and the
   upload/toast callbacks call _populateSkillsTab back in skills.js. Load order
   is free (both before main.js). Mirrors memory_skill_install.js.
   ════════════════════════════════════ */

// ── Drag-and-drop & file picker ────────────────────────────────

var _skillsDropAttached = false;

function _skillsAttachDropZone() {
  if (_skillsDropAttached) return;
  var panel = document.getElementById('settingsTab_skills');
  var zone = document.getElementById('skillsDropZone');
  if (!panel || !zone) return;
  // Shared OS-file .zip drag/drop wiring (core/zip_drop_zone.js). The upload +
  // toast callbacks stay local (skills-specific reload + body toast).
  _skillsDropAttached = attachZipDropZone({
    listenEl: panel,
    highlightEl: zone,
    onFile: function (f) { _skillsUploadZip(f); },
    onReject: function () { _skillsToast(t('skills.notZip'), 'error'); },
  });
}

function _skillsInstallFromInput(input) {
  var f = input && input.files && input.files[0];
  if (!f) return;
  _skillsUploadZip(f);
  input.value = '';
}

async function _skillsUploadZip(file) {
  _skillsToast(t('skills.installingFile', { name: file.name }));
  var fd = new FormData();
  fd.append('file', file);
  // Header selector (默认全局); falls back to global when the panel is absent.
  fd.append('scope', (typeof _skillsInstallScope === 'function') ? _skillsInstallScope() : 'global');
  try {
    var r = await Api.skills.install(fd);
    var d = (r ? await r.json().catch(function () { return {}; }) : {});
    if (!r || !r.ok) {
      _skillsToast(t('skills.installFailed', { err: (d.error || (r && r.statusText) || t('skills.noResponse')) }), 'error');
      return;
    }
    var hints = d.install_hints || [];
    var msg = t('skills.installedToast', { name: d.memory.name });
    if (hints.length) msg += t('skills.installHintSuffixUpload', { files: hints.map(function (h) { return h.file; }).join(', ') });
    _skillsToast(msg, 'success');
    // skills.js is DEFERRED (Epic-E sub-9): absent pre-land, the install
    // still succeeded — the tab list simply refreshes on next open.
    if (typeof _populateSkillsTab === 'function') await _populateSkillsTab();
  } catch (e) {
    _skillsToast(t('skills.installError', { err: e.message }), 'error');
  }
}

// ── Toast helper ──────────────────────────────────────────────

// ── Cross-modal entry: open Settings → Skills tab from Memory modal ──

function _openSkillsStoreFromMemory() {
  // Close memory modal first
  if (typeof closeMemoryModal === 'function') closeMemoryModal();
  // Open settings, then switch to Skills tab once it's open
  if (typeof openSettings === 'function') {
    openSettings();
    setTimeout(function () {
      if (typeof switchSettingsTab === 'function') switchSettingsTab('skills');
    }, 50);
  }
}

function _skillsToast(text, kind) {
  // Shared fade-out plumbing (core/toast.js::_ephemeralToast); keeps this
  // toast's document.body parent + 3-state .skills-toast class.
  var cls = 'skills-toast' + (kind === 'error' ? ' is-error' : kind === 'success' ? ' is-success' : '');
  _ephemeralToast(document.body, cls, text, kind === 'error' ? 5000 : 3500);
}

