          '<div class="stg-oauth-note-title">' + escapeHtml(t('settings.adapterManagedNoteTitle')) + '</div>' +
          '<div class="stg-oauth-note-desc">' + escapeHtml(t('settings.adapterManagedNoteDesc')) + '</div>' +
        '</div></div>';
